def count_collisions(keys, buckets):
    if buckets < 1:
        raise ValueError("buckets must be at least 1")
    seen = set()
    used = set()
    collisions = 0
    for key in keys:
        if key in seen:
            continue
        seen.add(key)
        bucket = key % buckets
        if bucket in used:
            collisions += 1
        else:
            used.add(bucket)
    return collisions

