from collections import deque


def shortest_path(graph, start, goal):
    if start not in graph:
        return None
    if start == goal:
        return [start]
    queue = deque([[start]])
    seen = {start}
    while queue:
        path = queue.popleft()
        for neighbour in graph.get(path[-1], []):
            if neighbour in seen:
                continue
            if neighbour == goal:
                return path + [neighbour]
            seen.add(neighbour)
            queue.append(path + [neighbour])
    return None

