def upsert(table, incoming):
    out = [dict(row) for row in table]
    where = {row["id"]: i for i, row in enumerate(out)}
    for row in incoming:
        if "id" not in row:
            raise ValueError("every row needs an id: %r" % (row,))
        key = row["id"]
        if key in where:
            out[where[key]].update(row)
        else:
            where[key] = len(out)
            out.append(dict(row))
    return out

